import { randomUUID } from "node:crypto";

export const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Matches keys generated by the server, without nested folders or traversal. */
export function isDocumentPath(path: unknown): path is string {
  if (typeof path !== "string") return false;
  const parts = path.split("/");
  return parts.length === 2 && UUID_PATTERN.test(parts[0]) &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}-[\w.-]{1,100}$/i.test(parts[1]);
}

export function documentPath(userId: string, filename: string): string {
  if (!UUID_PATTERN.test(userId)) throw new Error("Invalid storage owner");
  const safeName = filename.replace(/[^\w.-]+/g, "_").slice(-100) || "document";
  return `${userId}/${randomUUID()}-${safeName}`;
}
